-- 6. sınıf 2026-2027 Türkiye Yüzyılı Maarif Modeli hazırlığı.

DELETE s FROM ders_sorulari s INNER JOIN ders_konulari k ON k.id=s.konu_id WHERE k.kademe_kodu='temel_egitim' AND k.sinif_seviyesi=6;
DELETE FROM ders_konulari WHERE kademe_kodu='temel_egitim' AND sinif_seviyesi=6;
DELETE FROM ders_bolumleri WHERE kademe_kodu='temel_egitim' AND sinif_seviyesi=6;
